const nodeKey=(d,n)=>`${d}:${n}`;
const state={view:'overview',variant:['A','B','C'].includes(new URLSearchParams(location.search).get('variant'))?new URLSearchParams(location.search).get('variant'):'A',dept:'product',node:3,collapsed:false,project:'gagasort',projects:[{id:'gagasort',name:'GagaSort',type:'休闲解谜 · Unity',logo:'G'},{id:'newgame',name:'新游戏 · 立项演示',type:'空项目 · 等待定义',logo:'N'}],skills:{},outputs:{},logs:{},statuses:{},imports:{},openInputs:{},libraryDept:'all',casePage:1,caseSize:10,decision:0,decisions:['pending','pending','pending'],connection:{source:'local',protocol:'responses',endpoint:'',model:'gpt-6.1-sol',effort:'high',configPath:'',customModel:''},modal:null};
const projectDecisions={gagasort:state.decisions};
function activateProject(id){projectDecisions[state.project]=state.decisions;state.project=id;state.decisions=projectDecisions[id]??(projectDecisions[id]=['pending','pending','pending']);}
const project=()=>state.projects.find(x=>x.id===state.project);
const dept=()=>departments.find(x=>x.id===state.dept);
const currentNode=()=>dept().nodes[state.node];
const scoped=key=>`${state.project}:${key}`;
const lookup=(collection,d,n)=>collection[scoped(nodeKey(d,n))];
const setLookup=(collection,d,n,v)=>collection[scoped(nodeKey(d,n))]=v;
const tone=d=>`--dept:${d.color};--tint:${d.tint}`;
const sampleReady=(d,n)=>state.project==='gagasort'&&d==='product'&&n<3;
const status=(d,n)=>lookup(state.statuses,d,n)||(sampleReady(d,n)?'演示已确认':state.project==='gagasort'&&d==='product'&&n===3?'待你审核':'未开始');
function timestamp(){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date())}
function log(message,d=state.dept,n=state.node){const key=scoped(nodeKey(d,n));(state.logs[key]??=[]).unshift({time:timestamp(),message});}
function skill(d,n){return lookup(state.skills,d,n)||defaultSkill(d,n)}
function defaultSkill(d,n){const department=departments.find(x=>x.id===d),node=department.nodes[n];const special=d==='testing'&&n===0?'TEST_Test_Case':d==='testing'&&n===1?'TEST_Test_Codetest':`Studio_${d}_${n+1}`;return {name:special,origin:'默认 Skill',text:`---\nname: ${special}\ndescription: ${node[1]}\n---\n\n# ${node[1]}\n\n## 目标\n${node[3]}\n\n## 输入\n${node[5]}。逐项记录来源、版本和可读状态。没有取得的资料标记为缺口，禁止用猜测补齐。\n\n## 工作步骤\n1. 确定本次范围、上游已确认产物、可用工具与限制。\n2. 阅读范围内资料，建立来源与结论的对应关系。\n3. ${node[3]}\n4. 逐项复核结论、边界、跨部门依赖与未完成项。\n5. 按下述交付物输出，标明事实、假设与待确认问题。\n\n## 交付物\n${node[6]}。每项附来源、版本、检查范围和可验收条件。\n\n## 人工决策\n${node[4]}。未获得确认的方案不得作为下游已批准输入。\n\n## 质量与操作边界\n- 不编造数据、图片识别结果、代码证据或已执行状态。\n- 不把缺资料等同于产品缺陷，不把建议等同于审批结果。\n- 不擅自提交、拉取或推送 Git，不修改 Figma，不发布外部记录。\n- 仅对授权范围内的操作执行；出现缺口时保留已完成部分，说明下一步。\n${d==='testing'?'\n## 测试补充\n静态结论与运行验证分别记录。失败必须有可达反例，通过必须有完整断言证据。按确认根因合并缺陷；禁止伪造复现率或修复概率。\n':''}`}}
function sidebar(){const nav=(name,view,ico,count='')=>`<button class="nav-item ${state.view===view?'active':''}" data-action="view:${view}" title="${name}">${icon(ico)}<span class="label">${name}</span>${count?`<span class="count">${count}</span>`:''}</button>`;$('#sidebar').innerHTML=`<div class="brand"><div class="brand-mark">${icon('layers')}</div><span>StudioFlow<span style="color:#94a085;font-size:22px">.</span></span></div><div class="workspace-label"><span class="avatar">S</span><span>我的游戏工作室</span><span class="muted">⌄</span></div><div class="nav-label">WORKSPACE</div>${nav('项目总览','overview','grid')}${nav('项目产物','artifacts','folder')}${nav('待我决策','decisions','flag',String(state.decisions.filter(x=>x==='pending').length))}<div class="nav-label">AGENT DEPARTMENTS</div>${departments.map(d=>`<button class="nav-item ${state.view==='department'&&state.dept===d.id?'active':''}" data-action="dept:${d.id}" title="${d.title}" style="${tone(d)}"><i class="dept-dot"></i><span class="label">${d.title}</span></button>`).join('')}<div class="nav-label">RESOURCES</div>${nav('Skill 工作台','skills','spark')}${nav('连接与模型','settings','settings')}<div class="nav-spacer"></div><div class="sidebar-note"><strong>你的方法，就是竞争力</strong>每个节点都有默认 Skill<br>随时导入自己的工作方法</div><div class="user"><span class="avatar">YF</span><div><span class="small">工作室负责人</span><small>本地工作空间</small></div>${icon('down')}</div>`;}
function topbar(){const label=({overview:'项目总览',artifacts:'项目产物',decisions:'待我决策',skills:'Skill 工作台',settings:'连接与模型',department:dept().title})[state.view];$('#topbar').innerHTML=`<div class="breadcrumb">${button('','toggle-sidebar','ghost icon-button','menu')}<span>工作室</span><span class="separator">/</span><button class="project-trigger" data-action="projects"><span class="project-logo">${esc(project().logo)}</span>${esc(project().name)}${icon('down','small-icon')}</button><span class="separator">/</span><span class="page-crumb">${label}</span></div><div class="top-actions"><button class="ai-status" data-action="view:settings">${icon('spark','small-icon')}<span class="dot"></span>AI 待连接</button>${tag('交互原型')}<span class="avatar">YF</span></div>`}
function heading(title,desc,extra='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
function heroArt(){return `<div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit second"></div><div class="art-card"><div class="eyebrow" style="font-size:7px">IDEA → PRODUCT</div><div class="art-square">${icon('target')}</div><div class="art-line"></div><div class="art-line" style="width:90%"></div><div class="art-line" style="width:50%"></div></div><div class="art-card front"><div style="font-size:8px;letter-spacing:1px">READY TO BUILD</div><div class="art-square">${icon('layers')}</div><div class="art-line" style="width:85%"></div><div class="art-line" style="width:65%"></div></div><div class="art-badge">${icon('spark','small-icon')} 人的判断 × Agent 的执行</div></div>`}
const gateTitles=['机会是否值得验证','MVP 是否值得继续投入','版本是否可以上线','数据是否支持扩大投入'];
function overviewA(){return `${heading('把想法，推进成一款游戏。','一个项目，五个部门；每次交付，都有依据和下一步。',button('查看全链路','variant:B','','layers'),'YOUR GAME STUDIO')}<div class="hero-grid"><section class="hero"><div class="hero-copy"><div class="eyebrow">PROJECT MILESTONE / 01</div><h2>${state.project==='gagasort'?'从好点子，到值得做。':'从一个新想法开始。'}</h2><p>先确认玩家为什么玩、产品如何赚钱。<br>让调研、设计与实现围绕同一个目标推进。</p>${button('进入产品工作区','dept:product','lime','arrow')}</div>${heroArt()}</section><section class="panel gate-card"><div class="between"><span class="eyebrow">NEXT DECISION</span>${tag('人工决策','amber')}</div><h3>确认 MVP 范围，<br>再进入设计与开发</h3><p>范围、成本上限、验证标准。<br>让每次投入都有明确的边界。</p><div class="gate-foot"><span>演示决策 · 待审核</span>${button('审阅','decision:0','','arrow')}</div></section></div><div class="section-heading"><div class="row"><h2>部门协作</h2><span class="tiny muted">从机会到增长</span></div><span>22 个节点 · 每个节点均可替换 Skill</span></div><div class="department-cards">${departments.map((d,i)=>`<button class="panel department-card" style="${tone(d)}" data-action="dept:${d.id}"><div class="card-top"><div class="dept-symbol">${icon(d.icon)}</div><span>0${i+1}</span></div><h3>${d.title}</h3><p>${d.desc}</p><div class="step-bars">${d.nodes.map((n,j)=>`<i class="${sampleReady(d.id,j)?'done':state.project==='gagasort'&&i===0&&j===3?'current':''}"></i>`).join('')}</div><div class="card-foot"><span>${d.nodes.length} 个工作节点</span><span>${i===0&&state.project==='gagasort'?'查看示例 →':'进入 →'}</span></div></button>`).join('')}</div><div class="lower-grid"><section class="panel"><div class="panel-title"><h2>需要你的判断</h2>${tag('演示队列')}</div>${decisionItems.slice(0,2).map((x,i)=>`<div class="decision-row"><div class="decision-icon">${icon(x.icon)}</div><div><h3>${x.title}</h3><p>${x.department} · ${state.decisions[i]==='pending'?'待你确认':esc(state.decisions[i])}</p></div>${button('审阅',`decision:${i}`)}</div>`).join('')}<div class="panel-link"><span>重要的决定，由你掌握</span>${button('全部决策 →','view:decisions')}</div></section><section class="panel"><div class="panel-title"><h2>商业验证</h2>${tag('尚未接入真实数据')}</div><div class="business-list">${[['people','目标用户与使用动机','待调研验证'],['coins','变现模式与成本上限','待你设定'],['chart','留存 / LTV / 获客成本','暂无数据']].map(x=>`<div class="business-item"><span class="row">${icon(x[0],'small-icon')}${x[1]}</span><strong>${x[2]}</strong></div>`).join('')}</div><div class="panel-link"><span>阶段门槛 · 投入可控，结论可追溯</span>${button('设置门槛 →','business')}</div></section></div><p class="overview-note">${icon('info')}当前展示为演示项目流程，未运行 Agent 或连接外部服务。</p>`}
function overviewB(){return `${heading('从市场机会，到持续增长。','按交付物连接部门；节点产出经过确认，再交给下一环节。',button('设置阶段门槛','business','','flag'),'STUDIO PIPELINE')}<div class="blueprint-summary"><span><b>5</b>个部门</span><span><b>22</b>个可配置节点</span><span><b>4</b>个商业决策门槛</span><span>箭头表示交付方向，支持退回修改</span></div><div class="section-heading"><h2>项目全链路</h2><span>点击节点查看输入、产物与 Skill</span></div><div class="pipeline">${departments.map((d,i)=>`<section class="pipeline-row" style="${tone(d)}"><div class="pipeline-dept"><div class="dept-symbol">${icon(d.icon)}</div><div><h3>${d.title}</h3><p>${d.en}</p></div></div><div class="pipeline-nodes">${d.nodes.map((n,j)=>`<button class="pipeline-node ${status(d.id,j)!=='未开始'?'ready':''}" data-action="node:${d.id}:${j}"><span>0${i+1} / ${String(j+1).padStart(2,'0')}</span><b>${n[0]}</b><span class="node-status">${status(d.id,j)}</span></button>`).join('')}</div>${button('',`dept:${d.id}`,'department-link','arrow')}</section>`).join('')}</div><div class="pipeline-footer"><span>${icon('refresh','small-icon')} 发行数据回流产品，形成下一轮迭代</span>${button('查看节点 Skill','view:skills','ghost','spark')}</div><div class="info-strip">4 个决策门槛：机会验证 → MVP 投入 → 上线放行 → 规模化投入。你可以在任意阶段调整范围或退回上游。</div>`}
const decisionItems=[{title:'确认首版范围与验收标准',department:'产品部门',icon:'target',dept:'product',node:3,description:'首版先验证核心循环和商业化假设。审核本次必须做的内容、明确不做的内容，以及什么结果代表验证成功。',checks:['MVP 的核心玩法、首局路径和边界已明确','首版成本、时间与预算上限已确认','验证目标、数据口径与停止条件已明确'],files:['PRD_v0.1.md','玩法与商业化方案.md']},{title:'选择视觉方向与资产范围',department:'设计部门',icon:'brush',dept:'design',node:0,description:'在进入资产生产前，确认风格基准、可复用规则和首版必需资产。此处为决策界面示意，尚未生成真实设计稿。',checks:['视觉方向符合目标用户与玩法','关键页面、状态和适配要求已覆盖','首版资产范围和生产规格已确认'],files:['视觉方向板.md','资产清单.csv']},{title:'确认首轮商业实验预算',department:'发行与增长',icon:'chart',dept:'growth',node:1,description:'明确假设、预算上限和停止条件，再执行小规模实验。当前没有实际市场数据，不给出虚构的 ROI。',checks:['实验假设与对照方式清楚','预算上限、时间窗口与归因方式明确','成功标准与提前停止条件已确认'],files:['投放实验方案.md','商业验证门槛.md']}];
function overviewC(){return `${heading('让 Agent 推进，让你做决定。','把注意力放在范围、方向和投入；每个决策都关联上游依据。',button('查看全链路','variant:B','','layers'),'DECISION CENTER')}${decisionsBody()}`}
function decisionsBody(){const item=decisionItems[state.decision];return `<div class="decision-layout"><div class="panel decision-queue">${decisionItems.map((x,i)=>`<button class="queue-item ${state.decision===i?'active':''}" data-action="select-decision:${i}"><div class="between" style="width:100%"><span class="tiny muted">${x.department}</span>${tag(state.decisions[i]==='pending'?'待你确认':state.decisions[i],state.decisions[i]==='pending'?'amber':'green')}</div><h3>${x.title}</h3><p>演示任务 · 人工决策</p></button>`).join('')}</div><section class="panel decision-detail"><div class="between">${tag(item.department)}<span class="tiny muted">原型演示 · 不代表真实审批</span></div><h2>${item.title}</h2><p>${item.description}</p><div class="io-heading" style="margin-top:25px">关联产物<span>示例产物 · 非真实项目结论</span></div>${item.files.map(name=>`<div class="source-row"><span class="row">${icon('file','small-icon')}${name}</span>${button('预览',`preview:${item.dept}:${item.node}`,'ghost')}</div>`).join('')}<div class="checklist">${item.checks.map(t=>`<label><input type="checkbox" class="decision-check">${t}</label>`).join('')}</div><div class="field"><label for="decision-note">决策意见</label><textarea id="decision-note" placeholder="写下调整范围、退回原因或审批意见"></textarea></div><div class="approval-actions">${button('退回修改',`reject:${state.decision}`)}${button('确认并交付下游',`approve:${state.decision}`,'primary','check')}</div></section></div>`}
function departmentPage(){const d=dept(),n=currentNode(),sk=skill(d.id,state.node);return `<div class="page-heading"><div class="workspace-title" style="${tone(d)}"><span class="dept-symbol">${icon(d.icon)}</span><div><h1>${d.title}</h1><p>${d.desc} · 项目内的输入、产物和决策独立保存</p></div></div>${button('全链路','variant:B','','layers')}</div><nav class="workflow-strip" aria-label="${d.title}工作节点">${d.nodes.map((x,i)=>`<button class="workflow-step ${i===state.node?'active':''}" data-action="node:${d.id}:${i}" aria-current="${i===state.node?'step':'false'}"><span class="row"><span class="step-index">${i+1}</span><b>${x[0]}</b></span><span class="small">${status(d.id,i)}</span></button>`).join('')}</nav><div class="workspace-grid"><section class="panel"><div class="node-head"><h2>${n[1]}</h2>${tag(status(d.id,state.node),status(d.id,state.node)==='未开始'?'':'green')}</div><div class="skill-strip"><button class="skill-label" data-action="skill:${d.id}:${state.node}">${icon('spark')}${esc(sk.origin)} · ${esc(sk.name)}</button><div class="skill-actions">${button('导入 Skill',`import:${d.id}:${state.node}`,'','upload')}${button('导出 Skill',`export:${d.id}:${state.node}`,'','download')}</div></div><div class="panel-content"><p class="node-description">${n[3]}</p>${inputs(d,state.node)}${nodeOutput(d,state.node)}</div><div class="node-bottom"><span>当前操作仅作用于界面演示</span><div class="row">${button('重置节点',`reset:${d.id}:${state.node}`)}${button(lookup(state.outputs,d.id,state.node)?'查看交付决策':'预览生成结果',lookup(state.outputs,d.id,state.node)?`handoff:${d.id}:${state.node}`:`simulate:${d.id}:${state.node}`,'primary',lookup(state.outputs,d.id,state.node)?'arrow':'play')}</div></div></section><aside class="node-rail"><section class="panel rail-card"><span class="eyebrow">HUMAN CHECKPOINT</span><h3>${n[4]}</h3><p>上游输入、当前版本和交付缺口会一起进入决策，不自动跳过审核。</p><div class="decision-point"><b>交付给下一节点</b><br>${state.node<d.nodes.length-1?d.nodes[state.node+1][0]:departments[departments.indexOf(d)+1]?.title||'产品部门 · 下一轮迭代'}<br><span class="muted">产物：${n[2]}</span></div>${button('查看交付条件',`handoff:${d.id}:${state.node}`)}</section><section class="panel node-logs"><div class="panel-title"><h2>操作日志</h2><span class="tiny muted">北京时间</span></div><div class="log-body">${(lookup(state.logs,d.id,state.node)||[]).map(x=>`<div class="log-entry"><time>${x.time}</time>${esc(x.message)}</div>`).join('')||'<div class="log-entry">当前节点暂无操作记录。</div>'}</div></section></aside></div>`}
function inputs(d,n){const key=scoped(nodeKey(d.id,n)),opened=state.openInputs[key]||{},imports=state.imports[key]||[];return `<div class="io-section"><div class="io-heading">输入资料<span>${d.nodes[n][5]}</span></div><div class="import-choice">${button(`${icon(opened.links?'down':'plus','small-icon')} 飞书 / 网页链接`,`toggle-input:links`,opened.links?'expanded':'')}${button(`${icon(opened.files?'down':'plus','small-icon')} 本地文件`,`toggle-input:files`,opened.files?'expanded':'')}</div>${opened.links?`<div class="input-zone"><p>每行一个需求、资料或竞品链接</p><textarea id="source-links" placeholder="粘贴链接；当前原型仅演示导入状态"></textarea>${button('添加到输入','add-links','','link')}</div>`:''}${opened.files?`<div class="input-zone"><label class="file-drop">${icon('upload')}<br>选择文件或拖放至此<br><span class="tiny muted">当前仅记录文件名称，不上传或解析</span><input type="file" id="source-files" multiple hidden></label></div>`:''}${imports.map(x=>`<div class="source-row"><span class="row">${icon('file','small-icon')}${esc(x.name)}</span>${tag('已添加 · 未读取','amber')}</div>`).join('')}${state.project==='gagasort'&&d.id==='product'&&n===3?`<div class="source-row"><span class="row">${icon('file','small-icon')}上游：玩法与商业化方案.md</span>${tag('示例输入','green')}</div>`:''}</div>`}
function hasSample(d,n){if(lookup(state.statuses,d.id,n)==='未开始')return false;return state.project==='gagasort'&&(d.id==='product'&&n===3||d.id==='testing'&&n===0)}
function nodeOutput(d,n){if(!hasSample(d,n)&&!lookup(state.outputs,d.id,n))return `<div class="io-section"><div class="io-heading">预期交付<span>尚未生成</span></div><div class="empty-state">${icon('file')}<h3>${d.nodes[n][2]}</h3><p>${d.nodes[n][6]}</p><p style="margin-top:10px">添加输入后，可预览此节点的演示产物结构。</p></div></div>`;if(d.id==='testing'&&n===0)return testingOutput();return `<div class="io-section"><div class="io-heading">产物预览<span>预置示例 · 不代表已执行</span></div><div class="artifact-preview"><header><span class="row">${icon('file','small-icon')}${d.nodes[n][2]}</span>${tag('演示草稿')}</header><div class="artifact-content">${artifactContent(d,n)}</div></div></div>`}
function artifactContent(d,n){if(d.id==='product'&&n===3)return `<div class="eyebrow" style="margin-bottom:10px">PRODUCT REQUIREMENT / DRAFT</div><h3>休闲分类解谜 · MVP 需求结构</h3><p><b>核心目标</b>　验证“理解规则 → 操作分类 → 达成目标 → 获得反馈”的首局循环。</p><p><b>首版范围</b>　核心玩法、关卡配置、胜负结算与基础存档；扩展系统列为后续迭代。</p><div class="mock-image"><div><div class="mini-board"><i></i><i></i><i></i><i></i></div><div class="tiny" style="text-align:center;margin-top:10px">低保真占位 · 非实际游戏设计图</div></div></div><p><b>待确认问题</b>　首版投放地区、验证预算与商业化触点尚未定义。</p><p><b>验收要求</b>　每条规则关联入口、状态变化、异常边界和可观察结果。</p>`;return `<div class="eyebrow" style="margin-bottom:10px">${d.en} / SAMPLE DELIVERABLE</div><h3>${d.nodes[n][1]}</h3><p><b>输入依据</b>　${d.nodes[n][5]}。当前为结构示意，尚未读取真实资料。</p><p><b>本次交付</b>　${d.nodes[n][6]}。</p><ul><li>已确认事实：等待输入和证据</li><li>工作结论：尚未实际执行，不填造结论</li><li>待决策：${d.nodes[n][4]}</li><li>下游依赖：当前产物经你确认后交付</li></ul>${d.id==='design'?'<div class="mock-image">设计图预览区 · 尚未调用生图或设计工具</div>':''}`}
function testingOutput(){const cases=['新用户首次进入玩法','分类操作满足胜利条件','撤销操作恢复前一状态','配置为空时的可达行为','结算重复回调的奖励处理','跨日重登后的存档恢复','资源与关卡配置映射','失败后重开状态复位'];const total=470,pages=Math.ceil(total/state.caseSize),start=(state.casePage-1)*state.caseSize;return `<div class="io-section"><div class="io-heading">测试用例<span>470 条重复演示 · 仅用于分页预览</span></div><div class="table-scroll"><table><thead><tr><th>测试内容</th><th>覆盖点</th><th>状态</th></tr></thead><tbody>${Array.from({length:Math.min(state.caseSize,total-start)},(_,i)=>`<tr><td><b>${cases[(start+i)%cases.length]}</b><p>演示行 ${start+i+1} · 不代表真实测试点</p></td><td>规则 / 状态 / 边界</td><td>${tag('待审核')}</td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>共 470 条 · ${start+1}–${Math.min(start+state.caseSize,total)}</span><div class="row"><select id="case-size" aria-label="每页用例数量">${[10,20,50,100].map(x=>`<option ${x===state.caseSize?'selected':''}>${x}</option>`).join('')}</select><button data-action="case-page:-1" aria-label="上一页" ${state.casePage===1?'disabled':''}>‹</button><span>${state.casePage} / ${pages}</span><button data-action="case-page:1" aria-label="下一页" ${state.casePage===pages?'disabled':''}>›</button></div></div><details style="margin-top:20px"><summary class="small" style="cursor:pointer;color:#7f916e">覆盖缺口与确认问题 · 2 组</summary><div class="review-list"><div class="review-row"><div>配置边界值尚未定义<p>集中影响相关用例；确认一次，更新同组问题</p></div>${button('批量确认','review-group')}</div><div class="review-row"><div>界面表现缺少可读图稿<p>属于输入缺口，不能直接判断为产品缺陷</p></div>${button('补充资料','toggle-input:files')}</div></div></details></div>`}
function skillsPage(){const list=departments.filter(d=>state.libraryDept==='all'||d.id===state.libraryDept);return `${heading('把团队经验，变成可复用的 Skill。','所有 22 个节点都有默认规则；可以查看、替换、恢复和导出。',button('了解工作方式','skill-help','','info'),'SKILL WORKBENCH')}<div class="library-filters">${button('全部部门','filter-skill:all',state.libraryDept==='all'?'active':'')}${departments.map(d=>button(d.name,`filter-skill:${d.id}`,state.libraryDept===d.id?'active':'')).join('')}</div><div class="skill-grid">${list.flatMap(d=>d.nodes.map((n,i)=>{const sk=skill(d.id,i);return `<section class="panel skill-card" style="${tone(d)}"><div class="between"><span class="row"><span class="dept-symbol">${icon(d.icon)}</span><span class="tiny muted">${d.name} / ${i+1}</span></span>${tag(sk.origin,sk.origin==='已导入'?'blue':'')}</div><h3>${n[0]}</h3><p>${n[3]}</p><div class="between">${button('查看规则',`skill:${d.id}:${i}`)}<div class="row">${button('导入',`import:${d.id}:${i}`,'ghost','upload')}${button('导出',`export:${d.id}:${i}`,'ghost','download')}</div></div></section>`})).join('')}</div><p class="overview-note">${icon('info')}原型默认规则为模板；测试“用例 / 执行”默认内容来自你本地的 TEST_Test_Case / TEST_Test_Codetest 快照。</p>`}
function artifactsPage(){let items=[];if(state.project==='gagasort')items=departments[0].nodes.map((n,i)=>({d:departments[0],n:i,name:n[2],status:i<3?'演示已确认':'演示草稿'}));departments.forEach(d=>d.nodes.forEach((n,i)=>{if(lookup(state.outputs,d.id,i)&&!items.some(x=>x.d.id===d.id&&x.n===i))items.push({d,n:i,name:n[2],status:'演示草稿'})}));return `${heading('项目产物，一处追溯。','按部门和节点组织输入、版本与交付状态。',button('查看全链路','variant:B','','layers'),'PROJECT DELIVERABLES')}<div class="info-strip" style="margin-bottom:20px">此处只展示示例产物。没有真实执行，就不显示为正式交付。</div><div class="panel">${items.length?items.map(x=>`<div class="artifact-row">${icon('file')}<div><h3>${x.name}</h3><p>${x.d.title} / ${x.d.nodes[x.n][0]} · 示例版本 v0.1</p></div>${tag(x.status,x.status==='演示已确认'?'green':'amber')}<span class="small muted">示例产物</span>${button('查看',`preview:${x.d.id}:${x.n}`)}</div>`).join(''):'<div class="empty-state"><h3>此项目还没有产物</h3><p>先进入产品部门，从调研开始。</p></div>'}</div>`}
function modelForm(){const c=state.connection;return `<div class="connection-options"><label class="connection-option ${c.source==='local'?'selected':''}"><div class="row"><input type="radio" name="source" value="local" ${c.source==='local'?'checked':''}><h3>自动读取本机配置</h3></div><p>复用本机 Codex 登录或中转站<br>无需重复填写 API Key</p></label><label class="connection-option ${c.source==='api'?'selected':''}"><div class="row"><input type="radio" name="source" value="api" ${c.source==='api'?'checked':''}><h3>自定义 API</h3></div><p>填写供应商或中转站地址<br>指定协议、模型与凭据</p></label></div>${c.source==='local'?`<div class="info-strip">${icon('info','small-icon')}界面原型尚未读取你的本机配置。实际接入时按当前用户目录发现配置，不固定为开发者路径。</div><div class="field"><label for="config-path">配置文件位置 · 可选覆盖</label><input id="config-path" value="${esc(c.configPath)}" placeholder="自动发现当前用户的 Codex 配置；也可自行选择"></div><div class="field-row"><div class="field"><label for="model">期望使用的模型</label><input id="model" value="${esc(c.model)}" placeholder="供应商支持的模型 ID"></div><div class="field"><label for="effort">推理强度</label><select id="effort">${['low','medium','high','xhigh'].map(x=>`<option ${x===c.effort?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="small muted" style="margin-bottom:20px">期望配置：6.1 Sol / High。可用性与实际路由模型需连接后核实。</div>`:`<div class="field-row"><div class="field"><label for="protocol">接口协议</label><select id="protocol"><option value="responses" ${c.protocol==='responses'?'selected':''}>OpenAI Responses 兼容</option><option value="chat" ${c.protocol==='chat'?'selected':''}>OpenAI Chat Completions 兼容</option><option value="anthropic" ${c.protocol==='anthropic'?'selected':''}>Anthropic Messages</option><option value="gemini" ${c.protocol==='gemini'?'selected':''}>Google Gemini</option><option value="adapter" ${c.protocol==='adapter'?'selected':''}>其他 · 自定义适配器</option></select></div><div class="field"><label for="custom-model">模型 ID</label><input id="custom-model" value="${esc(c.customModel)}" placeholder="填写供应商的实际模型 ID"></div></div><div class="field"><label for="endpoint">API 地址</label><input id="endpoint" value="${esc(c.endpoint)}" placeholder="https://你的服务地址"></div><div class="field"><label for="api-key">API Key · 原型不保存密钥</label><input type="password" id="api-key" autocomplete="off" placeholder="界面演示无需填写真实密钥"></div><div class="info-strip" style="margin-bottom:20px">协议选项展示拟支持范围，尚未实现任何协议适配或模型连接。</div>`}<div class="connection-foot"><span>当前仅选择：${c.source==='local'?'本机配置':'自定义 API'} · 两种来源互斥</span><div class="row">${button('测试连接（演示）','test-connection')}${button('保存选择（演示）','save-connection','primary')}</div></div>`}
function settingsPage(){return `${heading('一次连接，整个工作室使用。','先连接大模型，再按需接入项目工具。每个节点都能看到使用的能力。','','CONNECTIONS')}<div class="settings-grid"><section class="panel settings-form"><div class="between"><h2>AI 大模型</h2>${tag('未连接','amber')}</div><p>选择一个配置来源。自动读取适合本地快速开始，自定义 API 适合团队或其他供应商。</p><div id="model-form">${modelForm()}</div></section><aside class="settings-connectors"><div class="eyebrow" style="margin-bottom:13px">按需接入的工具</div><section class="panel connector-card"><div class="between"><h3 class="row">${icon('folder')}本地项目</h3>${tag('未连接')}</div><p>选择游戏工程目录，识别本地分支和项目类型。路径由用户选择。</p>${button('选择项目目录','connector:project')}</section><section class="panel connector-card"><div class="between"><h3 class="row">${icon('file')}飞书</h3>${tag('未连接')}</div><p>导入需求、读取缺陷模板；发布前由你确认。</p>${button('连接飞书','connector:feishu')}</section><section class="panel connector-card"><div class="between"><h3 class="row">${icon('settings')}MCP 工具</h3>${tag('按需扩展')}</div><p>GM、资源工具或团队已有能力。未连接的能力明确保留缺口。</p>${button('管理工具','connector:mcp')}</section></aside></div>`}
function render({keepScroll=false}={}){const y=window.scrollY;sidebar();topbar();let html='';if(state.view==='overview')html=state.variant==='B'?overviewB():state.variant==='C'?overviewC():overviewA();else if(state.view==='department')html=departmentPage();else if(state.view==='skills')html=skillsPage();else if(state.view==='artifacts')html=artifactsPage();else if(state.view==='settings')html=settingsPage();else html=heading('关键决策，集中处理。','审核交付物、确认投入，把决定留在项目内。','','HUMAN DECISIONS')+decisionsBody();$('#content').innerHTML=html;document.body.classList.toggle('collapsed',state.collapsed);$('#prototype-switcher').innerHTML=`${button('←','cycle:-1','arrow')}<span>布局比较</span>${[['A','工作室总览'],['B','全链路'],['C','决策优先']].map(([v,t])=>button(v+' '+t,`variant:${v}`,state.view==='overview'&&state.variant===v?'active':'')).join('')}${button('→','cycle:1','arrow')}`;if(keepScroll)window.scrollTo(0,y);else window.scrollTo(0,0)}
function navigate(view){state.view=view;render()}
function openNode(d,n){state.dept=d;state.node=n;state.view='department';render()}
function variant(v){state.variant=v;state.view='overview';const u=new URL(location);u.searchParams.set('variant',v);history.replaceState(null,'',u);render()}
let toastTimer;function toast(message){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast">${esc(message)}</div>`;toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',3600)}
let scrollBeforeModal=0,previousFocus;
function modal(title,body,foot='',wide=false){if(!state.modal){scrollBeforeModal=window.scrollY;previousFocus=document.activeElement;const width=document.body.getBoundingClientRect().width;document.body.style.position='fixed';document.body.style.top=`-${scrollBeforeModal}px`;document.body.style.width=`${width}px`;document.body.style.overflow='hidden';state.modal=true;}$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2>${button('','close','ghost icon-button','close')}</div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}</section></div>`;requestAnimationFrame(()=>$('.modal [data-action="close"]')?.focus());}
function closeModal(){if(!state.modal)return;state.modal=null;$('#modal-root').innerHTML='';document.body.style.position='';document.body.style.top='';document.body.style.width='';document.body.style.overflow='';window.scrollTo(0,scrollBeforeModal);previousFocus?.focus({preventScroll:true});}
function projectPicker(){modal('选择项目',`<p>工作流、节点 Skill、产物和日志按项目区分。</p><input id="project-search" type="search" placeholder="搜索项目" style="width:100%"><div id="project-results"></div>`,`<span>每页最多 5 个项目</span>${button('新增项目','new-project','','plus')}`);renderProjects('');}
let projectPage=1;function renderProjects(query='',page=1){projectPage=page;const result=state.projects.filter(p=>p.name.toLowerCase().includes(query.toLowerCase()));const pages=Math.max(1,Math.ceil(result.length/5));$('#project-results').innerHTML=`<div class="project-results">${result.slice((page-1)*5,page*5).map(p=>`<button class="project-result ${p.id===state.project?'active':''}" data-action="project:${esc(p.id)}"><span class="project-info"><span class="project-logo">${esc(p.logo)}</span><span><h3>${esc(p.name)}</h3><p>${esc(p.type)}</p></span></span>${p.id===state.project?tag('当前项目','green'):icon('chevron','small-icon')}</button>`).join('')||'<p class="small muted">没有找到项目</p>'}</div><div class="pagination"><span>共 ${result.length} 个项目</span><div class="row"><button data-action="project-page:-1" ${page===1?'disabled':''}>‹</button><span>${page} / ${pages}</span><button data-action="project-page:1" ${page===pages?'disabled':''}>›</button></div></div>`;}
function showSkill(d,n){const sk=skill(d,n),department=departments.find(x=>x.id===d);modal(`${department.nodes[n][0]} · Skill`,`${tag(sk.origin,sk.origin==='已导入'?'blue':'green')} <span class="tiny muted">仅影响当前项目与当前节点</span><p style="margin-top:15px">${esc(sk.name)}${sk.snapshot?' · 本地 Skill 内容快照':' · 原型默认工作规则'}。导入后替换该节点规则，可随时恢复默认。</p><pre class="skill-text">${esc(sk.text)}</pre>`,`<span>导出为 Markdown 文件</span><div class="row">${sk.origin==='已导入'?button('恢复默认',`restore:${d}:${n}`):''}${button('导入 Skill',`import:${d}:${n}`,'','upload')}${button('导出 Skill',`export:${d}:${n}`,'primary','download')}</div>`,true)}
let pendingSkill;
function importSkill(d,n){pendingSkill={project:state.project,d,n};$('#skill-file').value='';$('#skill-file').click();}
function downloadSkill(d,n){const sk=skill(d,n),blob=new Blob([sk.text],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${sk.name.replace(/[^\p{L}\p{N}_-]/gu,'_')}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500);log('导出 Skill：'+sk.name,d,n);toast('已导出当前节点 Skill');if(!state.modal)render({keepScroll:true});}
function preview(d,n){const department=departments.find(x=>x.id===d);modal(department.nodes[n][2],`<div class="info-strip">预置示例 · 非真实执行产物</div><div class="artifact-content">${artifactContent(department,n)}</div>`,`<span>未写入外部系统</span>${button('前往节点',`goto:${d}:${n}`,'primary','arrow')}`,true)}
function handoff(d,n){const department=departments.find(x=>x.id===d);modal('确认节点交付',`<p>${department.nodes[n][4]}。此操作只演示审批，不会执行或发布。</p><div class="info-strip">当前产物仍为预置演示，不能据此认定真实工作已完成。</div><div class="checklist"><label><input type="checkbox" class="handoff-check">交付物、来源与版本已检查</label><label><input type="checkbox" class="handoff-check">覆盖缺口和下游依赖已明确</label></div>`,`<span>下一节点不会自动启动</span>${button('确认交付（演示）',`confirm-handoff:${d}:${n}`,'primary','check')}`)}
function saveModelFields(){const c=state.connection;for(const [id,key]of [['config-path','configPath'],['model','model'],['effort','effort'],['endpoint','endpoint'],['protocol','protocol'],['custom-model','customModel']]){const el=$('#'+id);if(el)c[key]=el.value}}
function business(){modal('商业验证门槛',`<p>先定义成功和停止的条件，再投入。指标门槛由项目目标决定，不预填虚假的行业标准。</p>${gateTitles.map((t,i)=>`<div class="field"><label for="business-${i}">0${i+1} · ${t}</label><textarea id="business-${i}" placeholder="填写证据要求、预算上限、指标和停止条件">${esc(lookup(state.outputs,'business',i)||'')}</textarea></div>`).join('')}`,`<span>仅保存在当前原型会话</span>${button('保存门槛','save-business','primary')}`)}
function action(code){const [a,b,c]=code.split(':');if(a==='view')navigate(b);else if(a==='dept')openNode(b,b==='product'?3:0);else if(a==='node')openNode(b,Number(c));else if(a==='toggle-sidebar'){state.collapsed=!state.collapsed;document.body.classList.toggle('collapsed',state.collapsed)}else if(a==='variant')variant(b);else if(a==='cycle'){const all=['A','B','C'];variant(all[(all.indexOf(state.variant)+Number(b)+3)%3])}else if(a==='projects')projectPicker();else if(a==='close')closeModal();else if(a==='project'){closeModal();activateProject(b);state.view='overview';state.casePage=1;render()}else if(a==='project-page')renderProjects($('#project-search').value,projectPage+Number(b));else if(a==='new-project'){modal('新增项目',`<p>项目资料、工作流和 Skill 独立管理，不会堆积到左侧导航。</p><div class="field"><label for="new-project-name">项目名称</label><input id="new-project-name" maxlength="80" placeholder="为新游戏起个名字"></div><div class="field"><label for="new-project-type">项目方向</label><input id="new-project-type" placeholder="例如：休闲解谜 / Unity / Android"></div>`,`<span>原型内存数据</span>${button('创建项目','create-project','primary','plus')}`)}else if(a==='create-project'){const name=$('#new-project-name').value.trim();if(!name)return toast('请填写项目名称');const id='project-'+Date.now();state.projects.push({id,name,type:$('#new-project-type').value.trim()||'新项目',logo:name[0].toUpperCase()});activateProject(id);closeModal();navigate('overview');toast('已创建演示项目')}else if(a==='skill')showSkill(b,Number(c));else if(a==='import')importSkill(b,Number(c));else if(a==='export')downloadSkill(b,Number(c));else if(a==='restore'){setLookup(state.skills,b,Number(c),null);log('恢复默认 Skill',b,Number(c));render({keepScroll:true});showSkill(b,Number(c));toast('已恢复默认 Skill')}else if(a==='filter-skill'){state.libraryDept=b;render({keepScroll:true})}else if(a==='skill-help'){modal('Skill 决定节点怎样工作',`<p>默认 Skill 提供基础方法。你可以导入自己的 Markdown 规则，替换当前项目的单个节点，再将它导出复用。</p><div class="info-strip">当前模板展示流程、规则和产物格式。真实执行、工具权限和质量保证需要后续单独设计，导入 Skill 本身不代表能力已经接通。</div>`,`<span>工作方法可复用，项目数据不混用</span>${button('知道了','close','primary')}`)}else if(a==='toggle-input'){const key=scoped(nodeKey(state.dept,state.node));(state.openInputs[key]??={})[b]=!state.openInputs[key][b];render({keepScroll:true})}else if(a==='add-links'){const links=$('#source-links').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!links.length)return toast('请先填写链接');if(links.some(x=>{try{return !['http:','https:'].includes(new URL(x).protocol)}catch{return true}}))return toast('请填写有效的 HTTP / HTTPS 链接');const key=scoped(nodeKey(state.dept,state.node));(state.imports[key]??=[]).push(...links.map(name=>({name})));log('添加 '+links.length+' 个链接；未读取远端内容');render({keepScroll:true});toast('链接已添加，原型未读取内容')}else if(a==='simulate'){setLookup(state.outputs,b,Number(c),true);setLookup(state.statuses,b,Number(c),'演示草稿');log('预览生成结果（演示，未调用模型）',b,Number(c));render({keepScroll:true});toast('已展示预置产物，未运行 Agent')}else if(a==='handoff')handoff(b,Number(c));else if(a==='confirm-handoff'){if([...document.querySelectorAll('.handoff-check')].some(x=>!x.checked))return toast('请先确认两项交付条件');setLookup(state.outputs,b,Number(c),true);setLookup(state.statuses,b,Number(c),'演示已确认');log('确认节点交付（演示）',b,Number(c));closeModal();const d=departments.find(x=>x.id===b),di=departments.indexOf(d);openNode(Number(c)<d.nodes.length-1?b:departments[(di+1)%departments.length].id,Number(c)<d.nodes.length-1?Number(c)+1:0);toast('已进入下一节点，未自动执行')}else if(a==='reset'){modal('重置当前节点',`<p>清除当前项目「${esc(currentNode()[0])}」的演示输入、产物和状态。保留 Skill；其他节点不受影响。</p>`,`<span>只重置当前节点</span>${button('确认重置',`confirm-reset:${b}:${c}`,'primary')}`)}else if(a==='confirm-reset'){const key=scoped(nodeKey(b,Number(c)));delete state.outputs[key];delete state.imports[key];state.statuses[key]='未开始';log('重置当前节点（保留 Skill）',b,Number(c));closeModal();render({keepScroll:true});toast('当前节点已重置')}else if(a==='preview')preview(b,Number(c));else if(a==='goto'){closeModal();openNode(b,Number(c))}else if(a==='case-page'){state.casePage+=Number(b);render({keepScroll:true})}else if(a==='review-group'){log('批量确认同组问题（演示）');render({keepScroll:true});toast('批量确认布局演示，未更改真实用例')}else if(a==='decision'){state.decision=Number(b);navigate('decisions')}else if(a==='select-decision'){state.decision=Number(b);render({keepScroll:true})}else if(a==='approve'||a==='reject'){if(a==='approve'&&[...document.querySelectorAll('.decision-check')].some(x=>!x.checked))return toast('请先确认决策检查项');const item=decisionItems[Number(b)];state.decisions[Number(b)]=a==='approve'?'演示已确认':'演示已退回';log(`${a==='approve'?'确认':'退回'}决策（演示）：${item.title}${$('#decision-note').value.trim()?'；意见：'+$('#decision-note').value.trim():''}`,item.dept,item.node);render({keepScroll:true});toast('已记录演示决策，未发布到外部系统')}else if(a==='business')business();else if(a==='save-business'){gateTitles.forEach((_,i)=>setLookup(state.outputs,'business',i,$('#business-'+i).value));closeModal();toast('商业门槛已保存到当前原型会话')}else if(a==='test-connection'){saveModelFields();toast('这是界面原型，尚未发起连接，也未读取本机配置')}else if(a==='save-connection'){saveModelFields();toast(`已选择${state.connection.source==='local'?'本机配置':'自定义 API'}，尚未连接`)}else if(a==='connector'){const names={project:'本地项目',feishu:'飞书',mcp:'MCP 工具'};modal(names[b]+' · 按需配置',`<p>这里预留${names[b]}接入入口，当前不连接或更改外部服务。</p><div class="field"><label for="connector-value">${b==='project'?'游戏工程目录':b==='feishu'?'飞书需求或 Bug 表链接':'MCP 服务配置'}</label><input id="connector-value" placeholder="后续实现时由用户选择或填写"></div>`,`<span>未配置 · 未连接</span>${button('返回','close','primary')}`)}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();if(!el.disabled)action(el.dataset.action)}else if(e.target.classList.contains('modal-backdrop'))closeModal()});
document.addEventListener('input',e=>{if(e.target.id==='project-search')renderProjects(e.target.value)});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='skill-file'&&el.files[0]){const target=pendingSkill,file=el.files[0];if(file.size>512000)return toast('Skill 文件过大，请控制在 500 KB 内');const text=await file.text();if(!text.trim())return toast('Skill 内容不能为空');const name=text.match(/^name:\s*["']?([^\r\n"']+)/m)?.[1]?.trim()||file.name.replace(/\.m(?:arkdown|d)$/i,'');state.skills[`${target.project}:${nodeKey(target.d,target.n)}`]={name,text,origin:'已导入'};log('导入 Skill：'+name,target.d,target.n);render({keepScroll:true});if(state.modal)showSkill(target.d,target.n);toast('已替换当前节点 Skill；刷新后恢复默认')}else if(el.id==='case-size'){state.caseSize=Number(el.value);state.casePage=1;render({keepScroll:true})}else if(el.name==='source'){saveModelFields();state.connection.source=el.value;$('#model-form').innerHTML=modelForm()}else if(el.id==='source-files'){const key=scoped(nodeKey(state.dept,state.node));(state.imports[key]??=[]).push(...[...el.files].map(f=>({name:f.name})));log('添加 '+el.files.length+' 个本地文件；未上传或解析');render({keepScroll:true});toast('已记录文件名称，未读取内容')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){e.preventDefault();closeModal();return}if(state.modal){if(e.key==='Tab'){const all=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);if(!all.length)return;const first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();action('cycle:'+(e.key==='ArrowRight'?1:-1))}});
document.addEventListener('dragover',e=>{if(e.target.closest('.file-drop'))e.preventDefault()});
document.addEventListener('drop',e=>{if(!e.target.closest('.file-drop'))return;e.preventDefault();const files=[...e.dataTransfer.files];const key=scoped(nodeKey(state.dept,state.node));(state.imports[key]??=[]).push(...files.map(f=>({name:f.name})));log('添加 '+files.length+' 个拖放文件；未上传或解析');render({keepScroll:true});toast('已记录文件名称，未读取内容')});
render();
// Bundle the user's existing test Skills as exact text snapshots for this read-only prototype.
fetch('test-skills.json').then(r=>{if(!r.ok)throw Error('snapshot missing');return r.json()}).then(data=>{const base=defaultSkill;defaultSkill=function(d,n){if(d==='testing'&&data[n])return {...data[n],origin:'默认 Skill',snapshot:true};return base(d,n)};if(state.view==='department'||state.view==='skills')render({keepScroll:true})}).catch(()=>{ /* Generic defaults remain clearly marked as prototype rules. */ });
